const body = $json.body || $json;
const phone = String(body.phone || '').trim();
const dnc = Boolean(body.do_not_contact);
const status = String(body.status || '').toLowerCase();
const timezone = String(body.timezone || 'America/New_York');
const blockedStatuses = new Set(['closed','dead','dnc','do_not_contact','stop','unresponsive_closed']);
let localHour = null;
let localTime = null;
try { const now = $now.setZone(timezone); localHour = now.hour; localTime = now.toISO(); } catch (e) { localHour = null; }
const reasons = [];
if (!phone) reasons.push('missing_phone');
if (dnc) reasons.push('do_not_contact');
if (blockedStatuses.has(status)) reasons.push('blocked_status');
if (localHour === null) reasons.push('invalid_timezone');
else if (localHour < 8 || localHour >= 21) reasons.push('outside_8am_9pm_local_window');
return [{ json: { allowed_to_contact: reasons.length === 0, reasons, phone, timezone, local_time: localTime, local_hour: localHour, operational_window: '08:00-21:00 local', compliance_note: 'Operational gate only; verify applicable federal/state consent and DNC requirements before outbound messaging.' } }];
